import java.util.*;
import java.io.*;

public class Main {
    static class Frac {
        long num, den;
        Frac(long num, long den) {
            this.num = num;
            this.den = den;
        }
    }

    static Pair<Long, Long> getRange(int x, int y, int b) {
        long low = (long) b * x / y;
        long high = ((long) b * x + y - 1) / y;
        return new Pair<>(low, high);
    }

    static long computeGCD(long a, long b) {
        while (b != 0) {
            long t = b;
            b = a % b;
            a = t;
        }
        return a;
    }

    static void findBestFraction(int x, int y, int n) {
        List<Frac> candidates = new ArrayList<>();
        for (int b = 1; b <= n; ++b) {
            Pair<Long, Long> range = getRange(x, y, b);
            candidates.add(new Frac(range.getKey(), b));
            candidates.add(new Frac(range.getValue(), b));
        }

        candidates.sort((f1, f2) -> {
            long diff1 = Math.abs((long) x * f1.den * f2.den - f1.num * f2.den * y);
            long diff2 = Math.abs((long) x * f1.den * f2.den - f2.num * f1.den * y);
            if (diff1 != diff2) return Long.compare(diff1, diff2);
            if (f1.den != f2.den) return Long.compare(f1.den, f2.den);
            return Long.compare(f1.num, f2.num);
        });

        Frac best = candidates.get(0);
        System.out.println(best.num + "/" + best.den);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        int x = Integer.parseInt(parts[0]);
        int y = Integer.parseInt(parts[1]);
        int n = Integer.parseInt(parts[2]);
        findBestFraction(x, y, n);
    }
}

